result.run_body:
for (int tick = 0; tick < ticks; tick++)
{
    foreach (var s in _replay.SpawnPlan.Where(x => x.Tick == tick))
        Spawn(s);
    foreach (var imp in _replay.Impulses.Where(x => x.Tick == tick))
        ApplyImpulse(imp);
    IntegrateMotion();
    DampenVelocities(tick);
    ComputeQuaternionScores(tick);
    ResolveCollisions(tick);
    ScanArena(tick);
}

result.dampen_body:
if (tick % 4 != 0)
    return;
foreach (var e in _entities)
{
    if (e.Velocity == Vector3.Zero)
        continue;
    e.Velocity = Vector3.Multiply(e.Velocity, 0.9f);
    _trace.UsedVector3Math = true;
    _events.Add(
        new Dictionary<string, object?>
        {
            ["type"] = "dampen",
            ["tick"] = tick,
            ["entity"] = e.Id,
            ["vx"] = e.Velocity.X,
            ["vy"] = e.Velocity.Y,
            ["vz"] = e.Velocity.Z,
        }
    );
}

result.quaternion_scores_body:
if (tick % 8 != 0)
    return;
foreach (var e in _entities)
{
    var v = e.Velocity;
    _quaternions.ComputeRotationScore(v.X, v.Y, v.Z, 45f);
    _quaternions.ComputeSlerpScore(0.5f, 0f, MathHelper.PiOver2);
    _quaternions.ComputeConcatenationScore(0.25f, 0.5f, 0.75f);
    _quaternions.ComputeInverseScore(v.X, v.Y, v.Z);
    _quaternions.ComputeLerpScore(0.5f, 0f, 1f);
    _trace.UsedQuaternionOps = true;
    _events.Add(_quaternions.BuildQuaternionSummary(e.Id, tick));
}

result.rotation_score_body:
var axis = new Vector3(vx, vy, vz);
var q = Quaternion.CreateFromAxisAngle(axis, MathHelper.ToRadians(angleDeg));
var m = Matrix.CreateFromQuaternion(q);
var v = Vector3.Transform(Vector3.UnitX, m);
float score = Vector3.Dot(v, axis);
_totalQuatScore += score;
_usedQuaternion = true;
return score;

result.slerp_score_body:
var from = Quaternion.CreateFromYawPitchRoll(fromAngle, 0f, 0f);
var to = Quaternion.CreateFromYawPitchRoll(toAngle, 0f, 0f);
var q = Quaternion.Slerp(from, to, t);
float score = q.Length();
_totalQuatScore += score;
_usedQuaternion = true;
return score;

result.concatenation_score_body:
var qy = Quaternion.CreateFromAxisAngle(Vector3.UnitY, yaw);
var qx = Quaternion.CreateFromAxisAngle(Vector3.UnitX, pitch);
var qz = Quaternion.CreateFromAxisAngle(Vector3.UnitZ, roll);
var q = Quaternion.Concatenate(Quaternion.Concatenate(qy, qx), qz);
q = Quaternion.Normalize(q);
float score = Quaternion.Dot(q, Quaternion.Identity);
_totalQuatScore += score;
_usedQuaternion = true;
return score;

result.inverse_score_body:
var axis = new Vector3(vx, vy, vz);
var q = Quaternion.CreateFromAxisAngle(axis, 0.5f);
var inv = Quaternion.Inverse(q);
var product = Quaternion.Multiply(q, inv);
float score = product.W;
_totalQuatScore += score;
_usedQuaternion = true;
return score;

result.lerp_score_body:
var q1 = new Quaternion(angle1, 0f, 0f, 1f);
var q2 = new Quaternion(0f, angle2, 0f, 1f);
var q = Quaternion.Lerp(q1, q2, t);
var m = Matrix.CreateFromQuaternion(q);
var v = Vector3.Transform(Vector3.UnitX, m);
float score = v.X;
_totalQuatScore += score;
_usedQuaternion = true;
return score;

